// Regenerates src/index.ts so every file in src/components/ui is exported.
// Run after `npx shadcn@latest add <component>`:  npm run gen:index
import { readdirSync, writeFileSync, existsSync } from "node:fs"

const files = (dir) =>
  existsSync(dir)
    ? readdirSync(dir).filter((f) => /\.tsx?$/.test(f)).map((f) => f.replace(/\.tsx?$/, "")).sort()
    : []

const lines = [
  '"use client"',
  "",
  "// Auto-generated by scripts/gen-index.mjs. Do not edit by hand.",
  "// Compiled into dist/styles.css at build time (not injected at runtime).",
  'import "./styles/globals.css"',
  'export * from "./lib/utils"',
  ...files("src/hooks").map((f) => `export * from "./hooks/${f}"`),
  ...files("src/components/ui").map((f) => `export * from "./components/ui/${f}"`),
  "",
]
writeFileSync("src/index.ts", lines.join("\n"))
console.log(`src/index.ts: ${lines.length - 5} modules exported`)
